import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Interface: CreateHostOptions","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"api/host/interfaces/CreateHostOptions.md","filePath":"api/host/interfaces/CreateHostOptions.md"}'),s={name:"api/host/interfaces/CreateHostOptions.md"};function l(n,e,d,c,i,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<p><a href="./../../packages">@oona/vlo</a> / <a href="./../">host</a> / CreateHostOptions</p><h1 id="interface-createhostoptions" tabindex="-1">Interface: CreateHostOptions <a class="header-anchor" href="#interface-createhostoptions" aria-label="Permalink to &quot;Interface: CreateHostOptions&quot;">​</a></h1><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L48" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:48</a></p><p>What <a href="./../functions/createHost">createHost</a> needs: durable stores, the registries, and which roles this process plays.</p><h2 id="extended-by" tabindex="-1">Extended by <a class="header-anchor" href="#extended-by" aria-label="Permalink to &quot;Extended by&quot;">​</a></h2><ul><li><a href="./ServeOptions"><code>ServeOptions</code></a></li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="activities" tabindex="-1">activities? <a class="header-anchor" href="#activities" aria-label="Permalink to &quot;activities?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>activities?</strong>: readonly <a href="./ActivityRegistration"><code>ActivityRegistration</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L61" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:61</a></p><p>Activities whose output schema the host enforces before folding a result. Unregistered activities still run; their output is folded as opaque JSON.</p><hr><h3 id="auth" tabindex="-1">auth? <a class="header-anchor" href="#auth" aria-label="Permalink to &quot;auth?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>auth?</strong>: <a href="./AuthConfig"><code>AuthConfig</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L71" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:71</a></p><p>Credentials for the control plane, inbound pushes, callbacks and signed links. Absent ⇒ open host.</p><hr><h3 id="basepath" tabindex="-1">basePath? <a class="header-anchor" href="#basepath" aria-label="Permalink to &quot;basePath?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>basePath?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L81" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:81</a></p><p>Path prefix this host is mounted under, e.g. <code>&quot;/api/vlo&quot;</code> for a Next route file at <code>app/api/vlo/[[...path]]/route.ts</code>. The router strips it before matching and every URL built from <code>publicUrl</code> carries it.</p><hr><h3 id="blob" tabindex="-1">blob? <a class="header-anchor" href="#blob" aria-label="Permalink to &quot;blob?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>blob?</strong>: <code>string</code> | <a href="./BlobStore"><code>BlobStore</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L52" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:52</a></p><p>A <code>BlobStore</code>, or a <code>file://</code> / <code>gcs://</code> URL to open. Default <a href="./../variables/DEFAULT_BLOB_URL">DEFAULT_BLOB_URL</a>.</p><hr><h3 id="dispatcher" tabindex="-1">dispatcher? <a class="header-anchor" href="#dispatcher" aria-label="Permalink to &quot;dispatcher?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>dispatcher?</strong>: <a href="./DispatcherOptions"><code>DispatcherOptions</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L89" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:89</a></p><p>Outbox dispatcher tuning. Only read when this host holds the <code>orchestrator</code> role.</p><hr><h3 id="domains" tabindex="-1">domains? <a class="header-anchor" href="#domains" aria-label="Permalink to &quot;domains?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>domains?</strong>: readonly <a href="./../../index/interfaces/Domain"><code>Domain</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L56" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:56</a></p><p>Domains from <code>defineDomain</code>; their registries are flattened onto the four arrays below.</p><hr><h3 id="journal" tabindex="-1">journal <a class="header-anchor" href="#journal" aria-label="Permalink to &quot;journal&quot;">​</a></h3><blockquote><p><strong>journal</strong>: <code>string</code> | <a href="./Journal"><code>Journal</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L50" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:50</a></p><p>A <code>Journal</code>, or a URL the host opens (and closes on <code>stop</code>).</p><hr><h3 id="kernel" tabindex="-1">kernel? <a class="header-anchor" href="#kernel" aria-label="Permalink to &quot;kernel?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>kernel?</strong>: <a href="./Kernel"><code>Kernel</code></a></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L87" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:87</a></p><p>Injected for tests; otherwise the wasm kernel is loaded on <code>start</code>.</p><hr><h3 id="namespace" tabindex="-1">namespace? <a class="header-anchor" href="#namespace" aria-label="Permalink to &quot;namespace?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>namespace?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L73" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:73</a></p><p>Namespace new runs are created in and <code>listRuns</code> filters by. Default <code>&quot;default&quot;</code>.</p><hr><h3 id="now" tabindex="-1">now? <a class="header-anchor" href="#now" aria-label="Permalink to &quot;now?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>now?</strong>: () =&gt; <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L85" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:85</a></p><p>Clock for every journaled timestamp, in epoch milliseconds. Default <code>Date.now</code>.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><hr><h3 id="publicurl" tabindex="-1">publicUrl? <a class="header-anchor" href="#publicurl" aria-label="Permalink to &quot;publicUrl?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>publicUrl?</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L75" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:75</a></p><p>Base URL peers reach this host on; fills <code>complete_url</code> on an outbound push.</p><hr><h3 id="queues" tabindex="-1">queues? <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;queues?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>queues?</strong>: <code>Record</code>&lt;<code>string</code>, <a href="./QueueConfig"><code>QueueConfig</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L69" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:69</a></p><p>Per-queue delivery: a push URL and secret, or <code>mode: &quot;pull&quot;</code>. Queues not listed are in-process only.</p><hr><h3 id="roles" tabindex="-1">roles? <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;roles?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>roles?</strong>: readonly <a href="./../type-aliases/Role"><code>Role</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L67" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:67</a></p><p>Roles this process holds. Default: <code>orchestrator</code>, <code>api</code>, plus one <code>worker:&lt;queue&gt;</code> per queue of every worker.</p><hr><h3 id="signals" tabindex="-1">signals? <a class="header-anchor" href="#signals" aria-label="Permalink to &quot;signals?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>signals?</strong>: readonly <a href="./SignalRegistration"><code>SignalRegistration</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L65" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:65</a></p><p>Signals whose payload the host validates before delivery. Unregistered signals pass through as-is.</p><hr><h3 id="streampollms" tabindex="-1">streamPollMs? <a class="header-anchor" href="#streampollms" aria-label="Permalink to &quot;streamPollMs?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>streamPollMs?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L83" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:83</a></p><p>How often an open SSE stream looks for new journal events. Default 500 ms.</p><hr><h3 id="workers" tabindex="-1">workers? <a class="header-anchor" href="#workers" aria-label="Permalink to &quot;workers?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>workers?</strong>: readonly <a href="./../../index/interfaces/Worker"><code>Worker</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L63" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:63</a></p><p>Workers run in this process. Each adds a <code>worker:&lt;queue&gt;</code> role when <code>roles</code> is absent.</p><hr><h3 id="workflows" tabindex="-1">workflows? <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;workflows?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>workflows?</strong>: readonly <a href="./../../index/interfaces/Workflow"><code>Workflow</code></a>&lt;<code>unknown</code>, <code>unknown</code>&gt;[]</p></blockquote><p>Defined in: <a href="https://github.com/oonalab/vlo/blob/a81c115e42e129b4efe8fd86066744a4f8bc3670/sdk/ts/sdk/src/host/roles.ts#L54" target="_blank" rel="noreferrer">sdk/ts/sdk/src/host/roles.ts:54</a></p><p>Workflows this host can run, by name. Starting an unregistered one is refused. Optional when <code>domains</code> supplies them.</p>',93)])])}const f=o(s,[["render",l]]);export{p as __pageData,f as default};
